import { env, exports as worker } from 'cloudflare:workers';
import { newHttpBatchRpcSession } from 'capnweb';
import { createKuratchiChannelClient } from '@kuratchi/koze';
import type { KuratchiChannelCallFrame } from '@kuratchi/koze';
import { afterEach, describe, expect, test, vi } from 'vitest';
// @ts-expect-error Internal route table generated by Koze.
import { routes } from 'koze:routes';

const channelUrl = 'https://example.com/__koze/channel';

interface RpcRoot {
	call(frame: KuratchiChannelCallFrame): Promise<unknown>;
}

function batch(session: string) {
	return newHttpBatchRpcSession<RpcRoot>(new Request(channelUrl, {
		method: 'POST',
		headers: { origin: 'https://example.com', cookie: `session=${session}` },
	}));
}

function interceptWorkerFetch() {
	const fetchWorker = vi.fn((input: RequestInfo | URL, init?: RequestInit) =>
		worker.default.fetch(new Request(input, init)));
	vi.stubGlobal('fetch', fetchWorker);
	return fetchWorker;
}

function inspect(slug: string | null, session: string) {
	const pathname = slug ? `/rpc/${slug}` : '/__koze/channel';
	const state = {
		slug, param: slug, localParam: slug, session,
		header: `session=${session}`,
		requestHeader: `session=${session}`,
		method: 'POST', pathname, url: pathname, query: slug ? 'detail' : null,
	};
	return { ok: true, value: { before: state, after: state } };
}

afterEach(() => vi.unstubAllGlobals());

describe('native Koze Worker', () => {
	test('renders a Koze route through the application-owned Worker', async () => {
		const response = await worker.default.fetch(new Request('https://example.com/'));
		expect(response.status).toBe(200);
		const html = await response.text();
		expect(html).toContain('Rendered by Koze inside workerd.');
		const nonce = response.headers.get('Content-Security-Policy')?.match(/'nonce-([^']+)'/)?.[1];
		expect(nonce).toBeTruthy();
		const scripts = html.match(/<script(?:\s[^>]*|)>/g) || [];
		expect(scripts.length).toBeGreaterThan(0);
		for (const script of scripts) expect(script).toContain(`nonce="${nonce}"`);
	});

	test('exports and calls a native Durable Object class', async () => {
		const stub = env.COUNTER.getByName('counter');
		expect(await stub.increment()).toBe(1);
		expect(await stub.increment()).toBe(2);
	});

	test('isolates overlapping route calls within a batch and across requests', async () => {
		const route = routes.find((route: { pattern: string }) => route.pattern.startsWith('/rpc/'));
		const module = route.module ?? await route.load();
		const [operation] = Object.keys(module.rpc);
		expect(operation).toMatch(/^rpc_/);

		const fetchWorker = interceptWorkerFetch();
		const first = batch('one');
		const second = batch('two');
		const call = (session: typeof first, slug: string, delay: number) =>
			session.call({ target: 'route', op: operation, route: `/rpc/${slug}?view=detail`, args: [delay] });
		await expect(Promise.all([
			call(first, 'first', 40),
			call(first, 'second', 20),
			call(second, 'third', 30),
		])).resolves.toEqual([
			inspect('first', 'one'),
			inspect('second', 'one'),
			inspect('third', 'two'),
		]);
		expect(fetchWorker).toHaveBeenCalledTimes(2);
	});

	test('isolates a failed operation from other calls in the HTTP batch', async () => {
		const fetchWorker = interceptWorkerFetch();
		const session = batch('one');
		const results = await Promise.all([
			session.call({ target: 'server', op: 'rpc/fail' }),
			session.call({ target: 'server', op: 'rpc/inspectContext', args: [0] }),
			session.call({ target: 'route', op: 'unused', route: 'https://other.example/rpc/first' }),
		]);
		expect(results[0]).toMatchObject({ ok: false, status: 500 });
		expect(results[1]).toEqual(inspect(null, 'one'));
		expect(results[2]).toMatchObject({ ok: false, status: 400 });
		expect(fetchWorker).toHaveBeenCalledTimes(1);
	});

	test('does not replay a committed mutation when the response is lost', async () => {
		vi.stubGlobal('window', { location: { pathname: '/' } });
		let responseStatus: number | undefined;
		const fetchWorker = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
			const request = new Request(input, init);
			request.headers.set('origin', 'https://example.com');
			const response = await worker.default.fetch(request);
			responseStatus = response.status;
			await response.text();
			throw new Error('Response lost');
		});
		vi.stubGlobal('fetch', fetchWorker);
		await expect(createKuratchiChannelClient().invoke({
			endpoint: channelUrl, target: 'server', op: 'rpc/increment', kind: 'mutation',
		})).rejects.toThrow('RPC transport failed');
		expect(responseStatus).toBe(200);
		expect(fetchWorker).toHaveBeenCalledTimes(1);
		expect(await env.COUNTER.getByName('lost-rpc-response').increment()).toBe(2);
	});

	test('preserves application-owned non-fetch handlers', async () => {
		await worker.default.queue?.(
			{ queue: 'jobs', messages: [] } as unknown as MessageBatch<unknown>,
			env,
			{} as ExecutionContext,
		);
		expect(await env.COUNTER.getByName('events').hasMark('queue:jobs')).toBe(true);

		await worker.default.scheduled?.(
			{ cron: '*/5 * * * *' } as ScheduledController,
			env,
			{} as ExecutionContext,
		);
		expect(await env.COUNTER.getByName('events').hasMark('scheduled:*/5 * * * *')).toBe(true);
	});
});
